        ...next,
        control1X: next.control1X + deltaX,
        control1Y: next.control1Y + deltaY,
      };
    }
  } else if (owned.type === 'cubic') {
    commands[commandIndex] =
      role === 'control1'
        ? { ...owned, control1X: point.x, control1Y: point.y }
        : { ...owned, control2X: point.x, control2Y: point.y };
  }
