    e: Number(draft.e),
    f: Number(draft.f),
  };
  const determinant = transform.a * transform.d - transform.b * transform.c;
  return Object.values(transform).every(Number.isFinite) && Math.abs(determinant) > 1e-12
    ? transform
    : null;
