function emptyPatch(): PixelPatch {
  return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };
}

function emptyCoveragePatch(): CoveragePatch {
  return { x: 0, y: 0, width: 0, height: 0, coverage: new Uint8ClampedArray() };
