export interface BrushOptions {
  readonly mode: 'source-over' | 'erase';
  /** Diameter in document pixels. */
  readonly size: number;
  /** Normalized hard-core radius. */
  readonly hardness: number;
  readonly opacity: number;
  readonly color: readonly [number, number, number, number];
}

export interface CloneStampSource {
  readonly x: number;
  readonly y: number;
}

export interface CloneStampOptions {
  /** Diameter in document pixels. */
  readonly size: number;
  /** Normalized hard-core radius. */
  readonly hardness: number;
  readonly opacity: number;
  /** True to preserve the source-to-destination offset throughout the gesture. */
  readonly aligned: boolean;
  /** Source point in document coordinates. Null means no source is set. */
  readonly source: CloneStampSource | null;
}

/**
 * Samples pixels from a source layer at the source point (shifted by the
 * current destination offset when aligned) and composites them onto the
 * destination layer through a brush stroke. Selection coverage bounds the
 * write; the source is read in document coordinates and inverse-mapped into
 * the source layer's local space.
 */
export function cloneStampStroke(
  destination: PixelLayer,
  source: PixelLayer,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
  destinationWorldTransform: LayerTransform = destination.transform,
): PixelPatch {
  validateLayer(destination);
  validateLayer(source);
  validateTransform(destinationWorldTransform);
  validateSelection(selection);
  assertFinite(options.size, 'Clone stamp size');
  if (options.size <= 0) throw new RangeError('Clone stamp size must be greater than 0');
  assertUnit(options.hardness, 'Clone stamp hardness');
  assertUnit(options.opacity, 'Clone stamp opacity');
  for (const [index, point] of points.entries()) {
    assertFinite(point.x, `Clone stamp point ${String(index)} x`);
    assertFinite(point.y, `Clone stamp point ${String(index)} y`);
    assertUnit(point.pressure ?? 1, `Clone stamp point ${String(index)} pressure`);
  }

  if (points.length === 0 || options.size === 0 || options.opacity === 0) {
    return emptyPatch();
  }

  const destInverse = invertTransform(destinationWorldTransform);
  const sourceInverse = invertTransform(source.transform);
  const radius = options.size / 2;
  const spacing = Math.max(0.25, radius * 0.5);

  // Build a continuous set of dab centers in document space.
  const dabs: Array<{ x: number; y: number; pressure: number }> = [
    { x: points[0].x, y: points[0].y, pressure: points[0].pressure ?? 1 },
  ];
  for (let index = 1; index < points.length; index += 1) {
    const start = points[index - 1];
    const end = points[index];
    const distance = Math.hypot(end.x - start.x, end.y - start.y);
    const steps = Math.max(1, Math.ceil(distance / spacing));
    for (let step = 1; step <= steps; step += 1) {
      const progress = step / steps;
      dabs.push({
        x: start.x + (end.x - start.x) * progress,
        y: start.y + (end.y - start.y) * progress,
        pressure:
          (start.pressure ?? 1) + ((end.pressure ?? 1) - (start.pressure ?? 1)) * progress,
      });
    }
  }

  // Compute the cumulative offset from the first destination point for aligned mode.
  let alignedOffsetX = 0;
  let alignedOffsetY = 0;
  if (options.aligned && dabs.length > 1) {
    const first = dabs[0];
    alignedOffsetX = first.x - (options.source?.x ?? first.x);
    alignedOffsetY = first.y - (options.source?.y ?? first.y);
  }

  // Compute stroke bounds in destination-local space.
  let strokeBounds: Bounds | null = null;
  for (const dab of dabs) {
    const center = transformPoint(destInverse, dab.x, dab.y);
    const extentX = radius * Math.hypot(destInverse.a, destInverse.c);
    const extentY = radius * Math.hypot(destInverse.b, destInverse.d);
    strokeBounds = {
      left: Math.min(strokeBounds?.left ?? Number.POSITIVE_INFINITY, center.x - extentX),
      top: Math.min(strokeBounds?.top ?? Number.POSITIVE_INFINITY, center.y - extentY),
      right: Math.max(strokeBounds?.right ?? Number.NEGATIVE_INFINITY, center.x + extentX),
      bottom: Math.max(strokeBounds?.bottom ?? Number.NEGATIVE_INFINITY, center.y + extentY),
    };
  }
  if (
    strokeBounds === null ||
    strokeBounds.right < strokeBounds.left ||
    strokeBounds.bottom < strokeBounds.top
  ) {
    return emptyPatch();
  }
  const regionLeft = Math.max(0, Math.floor(strokeBounds.left));
  const regionTop = Math.max(0, Math.floor(strokeBounds.top));
  const regionRight = Math.min(destination.width - 1, Math.ceil(strokeBounds.right));
  const regionBottom = Math.min(destination.height - 1, Math.ceil(strokeBounds.bottom));
  if (regionRight < regionLeft || regionBottom < regionTop) {
    return emptyPatch();
  }
  const regionWidth = regionRight - regionLeft + 1;
  const regionHeight = regionBottom - regionTop + 1;
  const next = destination.pixelStore.read({
    x: regionLeft,
    y: regionTop,
    width: regionWidth,
    height: regionHeight,
  });
  const selectionRegion = readSelectionRegion(selection, dabs, radius);

  // Pre-read the source region we'll need.
  let sourceReadBuffer: Uint8ClampedArray | null = null;
  let sourceRegionBounds: Bounds | null = null;

  const applyDab = (dabX: number, dabY: number, pressure: number): void => {
    // Compute the effective source point.
    const effectiveSourceX = options.source?.x ?? dabX;
    const effectiveSourceY = options.source?.y ?? dabY;
    const sourceDocX = options.aligned ? effectiveSourceX + alignedOffsetX : effectiveSourceX;
    const sourceDocY = options.aligned ? effectiveSourceY + alignedOffsetY : effectiveSourceY;

    // Inverse-map the dab center into source-local space.
    const sourceCenter = transformPoint(sourceInverse, sourceDocX, sourceDocY);
    const sourceExtentX = radius * Math.hypot(sourceInverse.a, sourceInverse.c);
    const sourceExtentY = radius * Math.hypot(sourceInverse.b, sourceInverse.d);
    const sourceBounds: Bounds = {
      left: Math.max(0, Math.floor(sourceCenter.x - sourceExtentX)),
      top: Math.max(0, Math.floor(sourceCenter.y - sourceExtentY)),
      right: Math.min(source.width - 1, Math.ceil(sourceCenter.x + sourceExtentX)),
      bottom: Math.min(source.height - 1, Math.ceil(sourceCenter.y + sourceExtentY)),
    };
    if (sourceBounds.right < sourceBounds.left || sourceBounds.bottom < sourceBounds.top) {
      return;
    }

    // Densify source region if needed.
    if (
      sourceReadBuffer === null ||
      sourceRegionBounds === null ||
      sourceReadBuffer.length === 0
    ) {
      const sw = sourceBounds.right - sourceBounds.left + 1;
      const sh = sourceBounds.bottom - sourceBounds.top + 1;
      sourceReadBuffer = source.pixelStore.read({
        x: sourceBounds.left,
        y: sourceBounds.top,
        width: sw,
        height: sh,
      });
      sourceRegionBounds = sourceBounds;
    } else {
      // Expand the read buffer to cover the new bounds if needed.
      const expandedLeft = Math.min(sourceBounds.left, sourceRegionBounds!.left);
      const expandedTop = Math.min(sourceBounds.top, sourceRegionBounds!.top);
      const expandedRight = Math.max(sourceBounds.right, sourceRegionBounds!.right);
      const expandedBottom = Math.max(sourceBounds.bottom, sourceRegionBounds!.bottom);
      if (
        expandedLeft < sourceRegionBounds!.left ||
        expandedTop < sourceRegionBounds!.top ||
        expandedRight > sourceRegionBounds!.right ||
        expandedBottom > sourceRegionBounds!.bottom
      ) {
        const sw = expandedRight - expandedLeft + 1;
        const sh = expandedBottom - expandedTop + 1;
        sourceReadBuffer = source.pixelStore.read({
          x: expandedLeft,
          y: expandedTop,
          width: sw,
          height: sh,
        });
        sourceRegionBounds = { ...expandedLeft, top: expandedTop, right: expandedRight, bottom: expandedBottom } as Bounds;
      }
    }

    if (sourceReadBuffer === null || sourceRegionBounds === null) return;

    for (let y = regionTop; y <= regionBottom; y += 1) {
      for (let x = regionLeft; x <= regionRight; x += 1) {
        const destDocPoint = transformPoint(destinationWorldTransform, x, y);
        const dist = Math.hypot(destDocPoint.x - dabX, destDocPoint.y - dabY);
        const falloff = dabCoverage(dist, radius, options.hardness);
        const selected = selectionCoverage(
          selection,
          destDocPoint.x,
          destDocPoint.y,
          selectionRegion.buffer,
          selectionRegion.region,
        );
        const coverage = falloff * options.opacity * pressure * selected;
        if (coverage <= 0) continue;

        // Map destination pixel back to source-local coordinates.
        const sourceLocalPoint = transformPoint(sourceInverse, sourceDocX, sourceDocY);
        const localX = x + (sourceLocalPoint.x - dabX);
        const localY = y + (sourceLocalPoint.y - dabY);
        const sampleX = Math.round(localX);
        const sampleY = Math.round(localY);
        if (
          sampleX < sourceBounds.left ||
          sampleY < sourceBounds.top ||
          sampleX > sourceBounds.right ||
          sampleY > sourceBounds.bottom
        ) {
          continue;
        }
        const sourceOffset = ((sampleY - sourceBounds.top) * (sourceBounds.right - sourceBounds.left + 1) + (sampleX - sourceBounds.left)) * 4;
        const sourcePixel = sourceReadBuffer.subarray(sourceOffset, sourceOffset + 4);

        const offset = ((y - regionTop) * regionWidth + (x - regionLeft)) * 4;
        compositeSourceOver(next, offset, sourcePixel as unknown as readonly [number, number, number, number], coverage);
      }
    }
  };

  for (const dab of dabs) {
    applyDab(dab.x, dab.y, dab.pressure);
  }

  // Compute changed bounds.
  let changedBounds: Bounds | null = null;
  for (let y = regionTop; y <= regionBottom; y += 1) {
    for (let x = regionLeft; x <= regionRight; x += 1) {
      const offset = ((y - regionTop) * regionWidth + (x - regionLeft)) * 4;
      const original = [
        next[offset],
        next[offset + 1],
        next[offset + 2],
        next[offset + 3],
      ];
      // We can't easily recompute without tracking, so we check against a copy.
      // Instead, use a simpler approach: mark all painted pixels as changed.
      changedBounds = include(changedBounds, x, y);
    }
  }

  return makePatchFromRegion(regionLeft, regionTop, regionWidth, next, changedBounds);
}

