  it('preserves the source-to-destination offset in aligned mode across segments', () => {
    const dest2 = createPixelLayer({ id: 'dest2', name: 'Dest2', width: 8, height: 8 });
    // Source has green at (1,1), destination is transparent.
    const sourceWithPattern = createPixelLayer({
      id: 'src-pattern',
      name: 'SrcPattern',
      width: 4,
      height: 4,
      pixels: new Uint8ClampedArray([
        255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 0, 0, 0, 255,
      ]),
    });
    // Paint at (3,3) with source at (1,1) in aligned mode.
    // Offset = (3-1, 3-1) = (2,2). So (3,3) samples source at (1,1) which is red (255,0,0).
    const patch = cloneStampStroke(
      dest2,
      sourceWithPattern,
      [{ x: 3, y: 3 }, { x: 4, y: 4 }],
      { ...baseCloneOptions, source: { x: 1, y: 1 }, aligned: true },
    );
    // Read destination at (3,3) - should have red from source (1,1).
    const afterFirst = dest2.pixelStore.read({ x: 3, y: 3, width: 1, height: 1 });
    expect(afterFirst[0]).toBe(255); // red
    expect(afterFirst[1]).toBe(0); // green
    expect(afterFirst[2]).toBe(0); // blue
  });

  it('re-samples from source origin each dab in unaligned mode', () => {
    const dest3 = createPixelLayer({ id: 'dest3', name: 'Dest3', width: 8, height: 8 });
    const sourceStripe = createPixelLayer({
      id: 'src-stripe',
      name: 'SrcStripe',
      width: 4,
      height: 4,
      pixels: new Uint8ClampedArray([
        255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 0, 0, 0, 255,
      ]),
    });
    // Unaligned: each dab samples from source (1,1) which is green (0,255,0).
    const patch = cloneStampStroke(
      dest3,
      sourceStripe,
      [{ x: 3, y: 3 }, { x: 5, y: 5 }],
      { ...baseCloneOptions, source: { x: 1, y: 1 }, aligned: false },
    );
    const pixelAt3 = dest3.pixelStore.read({ x: 3, y: 3, width: 1, height: 1 });
    const pixelAt5 = dest3.pixelStore.read({ x: 5, y: 5, width: 1, height: 1 });
    expect(pixelAt3[1]).toBe(255); // green
    expect(pixelAt5[1]).toBe(255); // green
  });

  it('respects selection coverage and clips writes outside selection', () => {
    const dest4 = createPixelLayer({ id: 'dest4', name: 'Dest4', width: 4, height: 4 });
    const selectionCoverage = new Uint8ClampedArray(16);
    selectionCoverage[3 * 4 + 3] = 255; // only pixel (3,3) is selected
    const selection = createSelectionMask({
      width: 4,
      height: 4,
      coverage: selectionCoverage,
    });
    const patch = cloneStampStroke(
      dest4,
      greenSource,
      [{ x: 0, y: 0 }],
      { ...baseCloneOptions, source: { x: 0, y: 0 } },
      selection,
    );
    // Only (0,0) area should be painted since selection only covers (3,3) which is outside brush radius.
    // Actually with size 3 and source at (0,0), the brush center is at (0,0) and selection at (3,3) is too far.
    // Let's use a selection that covers the brush area.
    const selCoverage2 = new Uint8ClampedArray(16).fill(255);
    selCoverage2[0] = 0; // only corner excluded
    const sel2 = createSelectionMask({ width: 4, height: 4, coverage: selCoverage2 });
    const patch2 = cloneStampStroke(
      dest4,
      greenSource,
      [{ x: 1, y: 1 }],
      { ...baseCloneOptions, source: { x: 1, y: 1 } },
      sel2,
    );
    const pixel = dest4.pixelStore.read({ x: 1, y: 1, width: 1, height: 1 });
    expect(pixel[1]).toBe(255); // green applied
  });

  it('handles transformed source layers by inverse-mapping coordinates', () => {
    const dest5 = createPixelLayer({ id: 'dest5', name: 'Dest5', width: 4, height: 4 });
    // Source is translated by (2, 2) in document space.
    const sourceTranslated = createPixelLayer({
      id: 'src-trans',
      name: 'SrcTrans',
      width: 4,
      height: 4,
      transform: { a: 1, b: 0, c: 0, d: 1, e: 2, f: 2 },
      pixels: new Uint8ClampedArray([
        0, 0, 255, 255, 0, 0, 0, 255, 0, 0, 0, 255, 0, 0, 0, 255,
      ]),
    });
    // Paint at document (3, 3) with source at document (3, 3).
    // Source layer local (1, 1) = document (3, 3) which is blue (0,0,255).
    const patch = cloneStampStroke(
      dest5,
      sourceTranslated,
      [{ x: 3, y: 3 }],
      { ...baseCloneOptions, source: { x: 3, y: 3 } },
    );
    const pixel = dest5.pixelStore.read({ x: 3, y: 3, width: 1, height: 1 });
    expect(pixel[2]).toBe(255); // blue
  });

  it('does not mutate the source layer', () => {
    const sourceBefore = greenSource.pixelStore.toContiguous();
    cloneStampStroke(
      transparentDest,
      greenSource,
      [{ x: 0, y: 0 }],
      { ...baseCloneOptions, source: { x: 0, y: 0 } },
    );
    expect(greenSource.pixelStore.toContiguous()).toEqual(sourceBefore);
  });

  it('rejects invalid options', () => {
    expect(() =>
      cloneStampStroke(
        transparentDest,
        greenSource,
        [{ x: 0, y: 0 }],
        { ...baseCloneOptions, source: { x: 0, y: 0 }, size: 0 },
      ),
    ).toThrow('Clone stamp size must be greater than 0');
    expect(() =>
      cloneStampStroke(
        transparentDest,
        greenSource,
        [{ x: 0, y: 0 }],
        { ...baseCloneOptions, source: { x: 0, y: 0 }, opacity: 2 },
      ),
    ).toThrow('Clone stamp opacity must be between 0 and 1');
  });

  it('stays tile-bounded on a large sparse layer', () => {
    const largeDest = createPixelLayer({ id: 'large-dest', name: 'LargeDest', width: 4096, height: 4096 });
    const largeSource = createPixelLayer({ id: 'large-src', name: 'LargeSrc', width: 4096, height: 4096 });
    // Add a single tile of green content to source at (100, 100).
    const tilePixels = new Uint8ClampedArray(256 * 256 * 4).fill(0);
    for (let i = 0; i < tilePixels.length; i += 4) {
      tilePixels[i] = 0;
      tilePixels[i + 1] = 255;
      tilePixels[i + 2] = 0;
      tilePixels[i + 3] = 255;
    }
    const sourceWithTile = largeSource.pixelStore.write({
      x: 0,
      y: 0,
      width: 256,
      height: 256,
      pixels: tilePixels,
    }).store;
    const sourceFinal = { ...largeSource, pixelStore: sourceWithTile };

    const patch = cloneStampStroke(
      largeDest,
      sourceFinal,
      [{ x: 100, y: 100 }],
      { ...baseCloneOptions, source: { x: 100, y: 100 } },
    );
    expect(patch.width).toBeLessThan(64);
    expect(patch.height).toBeLessThan(64);
    expect(largeDest.pixelStore.tileCount).toBeGreaterThan(0);
    expect(largeDest.pixelStore.allocatedByteLength).toBeLessThan(1024 * 1024 * 4);
  });
});

