it('preserves the source-to-destination offset in aligned mode across segments', () => {
  const dest2 = createPixelLayer({ id: 'dest2', name: 'Dest2', width: 8, height: 8 });
  // Source has green at (1,1), destination is transparent.
  const sourceWithPattern = createPixelLayer({
    id: 'src-pattern',
    name: 'SrcPattern',
    width: 4,
    height: 4,
    pixels: new Uint8ClampedArray([
      255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 0, 0, 0, 255,
    ]),
  });
  // Paint at (3,3) with source at (1,1) in aligned mode.
  // Offset = (3-1, 3-1) = (2,2). So (3,3) samples source at (1,1) which is red (255,0,0).
  const patch = cloneStampStroke(
    dest2,
    sourceWithPattern,
    [{ x: 3, y: 3 }, { x: 4, y: 4 }],
    { ...baseCloneOptions, source: { x: 1, y: 1 }, aligned: true },
  );
  // Read destination at (3,3) - should have red from source (1,1).
  const afterFirst = dest2.pixelStore.read({ x: 3, y: 3, width: 1, height: 1 });
  expect(afterFirst[0]).toBe(255); // red
  expect(afterFirst[1]).toBe(0); // green
  expect(afterFirst[2]).toBe(0); // blue
});

