it('stays tile-bounded on a large sparse layer', () => {
  const largeDest = createPixelLayer({ id: 'large-dest', name: 'LargeDest', width: 4096, height: 4096 });
  const largeSource = createPixelLayer({ id: 'large-src', name: 'LargeSrc', width: 4096, height: 4096 });
  // Add a single tile of green content to source at (0, 0).
  const tilePixels = new Uint8ClampedArray(256 * 256 * 4).fill(0);
  for (let i = 0; i < tilePixels.length; i += 4) {
    tilePixels[i] = 0;
    tilePixels[i + 1] = 255;
    tilePixels[i + 2] = 0;
    tilePixels[i + 3] = 255;
  }
  const sourceWithTile = largeSource.pixelStore.write({
    x: 0,
    y: 0,
    width: 256,
    height: 256,
    pixels: tilePixels,
  }).store;
  const sourceFinal: import('@freetoshop/core-document').PixelLayer = {
    ...largeSource,
    pixelStore: sourceWithTile,
  };

  const patch = cloneStampStroke(
    largeDest,
    sourceFinal,
    [{ x: 100, y: 100 }],
    { ...baseCloneOptions, source: { x: 100, y: 100 } },
  );
  expect(patch.width).toBeLessThan(64);
  expect(patch.height).toBeLessThan(64);
  // Apply patch to trigger tile write.
  const doc = createDocument({ id: 'large-test', name: 'LargeTest', width: 4096, height: 4096, layers: [largeDest] });
  const next = patchPixels(largeDest.id, patch).execute(doc);
  const finalDest = next.layers[0] as import('@freetoshop/core-document').PixelLayer;
  expect(finalDest.pixelStore.tileCount).toBeGreaterThan(0);
  expect(finalDest.pixelStore.allocatedByteLength).toBeLessThan(1024 * 1024 * 4);
});

