      return { type, brightness: 0, contrast: 0 };
    case 'levels':
      return { type, inputBlack: 0, inputWhite: 255, gamma: 1, outputBlack: 0, outputWhite: 255 };
    case 'hue-saturation':
      return { type, hue: 0, saturation: 0, lightness: 0 };
    case 'invert':
