  const bounds = stage.getBoundingClientRect();
  const point = {
    x: (clientX - bounds.left - viewport.panX) / viewport.zoom,
    y: (clientY - bounds.top - viewport.panY) / viewport.zoom,
  };
  return applyGuideSnap(point, viewport, snap);
}

