// Manage a source read buffer that covers all needed samples.
let sourceReadBuffer: Uint8ClampedArray | null = null;
let sourceReadBounds: Bounds | null = null;

const ensureSourceRead = (bounds: Bounds): void => {
  if (sourceReadBounds === null) {
    const sw = bounds.right - bounds.left + 1;
    const sh = bounds.bottom - bounds.top + 1;
    sourceReadBuffer = source.pixelStore.read({ x: bounds.left, y: bounds.top, width: sw, height: sh });
    sourceReadBounds = bounds;
    return;
  }
  const current = sourceReadBounds;
  const needsExpand =
    bounds.left < current.left ||
    bounds.top < current.top ||
    bounds.right > current.right ||
    bounds.bottom > current.bottom;
  if (!needsExpand) return;
  const expandedLeft = Math.min(bounds.left, current.left);
  const expandedTop = Math.min(bounds.top, current.top);
  const expandedRight = Math.max(bounds.right, current.right);
  const expandedBottom = Math.max(bounds.bottom, current.bottom);
  const sw = expandedRight - expandedLeft + 1;
  const sh = expandedBottom - expandedTop + 1;
  sourceReadBuffer = source.pixelStore.read({ x: expandedLeft, y: expandedTop, width: sw, height: sh });
  sourceReadBounds = { left: expandedLeft, top: expandedTop, right: expandedRight, bottom: expandedBottom };
