  const destLayer2 = next2.layers[0] as import('@freetoshop/core-document').PixelLayer;
  // (3,3) should have green from source (1,1).
  expect(destLayer2.pixelStore.read({ x: 3, y: 3, width: 1, height: 1 })[1]).toBe(255); // green
});

