it('handles transformed source layers by inverse-mapping coordinates', () => {
  const dest5 = createPixelLayer({ id: 'dest5', name: 'Dest5', width: 4, height: 4 });
  // Source is translated by (2, 2) in document space.
  // Local (1,1) = document (3,3). Set pixel (1,1) to blue.
  const srcPixels = new Uint8ClampedArray(4 * 4 * 4);
  // Fill with black, then set (1,1) to blue.
  srcPixels[1 * 4 * 4 + 2] = 255; // blue at local (1,1)
  const sourceTranslated = createPixelLayer({
    id: 'src-trans',
    name: 'SrcTrans',
    width: 4,
    height: 4,
    transform: { a: 1, b: 0, c: 0, d: 1, e: 2, f: 2 },
    pixels: srcPixels,
  });
  // Paint at document (3, 3) with source at document (3, 3).
  // Source inverse maps doc (3,3) to local (1,1) = blue.
  const patch = cloneStampStroke(
    dest5,
    sourceTranslated,
    [{ x: 3, y: 3 }],
    { ...baseCloneOptions, source: { x: 3, y: 3 } },
  );
  const pixel = dest5.pixelStore.read({ x: 3, y: 3, width: 1, height: 1 });
  expect(pixel[2]).toBe(255); // blue
});

